// Default to a restricted test query until a person explicitly chooses discovery mode.
return $input.all().map(item => {
  const j = item.json || {};
  const mode = String(j.gmailSearchMode || 'test').trim().toLowerCase();
  return { json: { ...j, activeGmailQuery: mode === 'discovery' ? j.gmailDiscoveryQuery : j.gmailTestQuery } };
});

// Redact secrets before AI and keep only source-backed value candidates.
let config = {};
try { config = $('Set Template Fields').first().json || {}; } catch (error) {}
const results = [];
function header(item, name) {
  const headers = item.json?.payload?.headers || item.json?.headers || [];
  const found = Array.isArray(headers) ? headers.find(h => String(h.name || '').toLowerCase() === name.toLowerCase()) : null;
  return String(found?.value || item.json?.[name.toLowerCase()] || item.json?.[name] || '');
}
function redact(value) {
  let text = String(value || '').replace(/<[^>]*>/g, ' ');
  text = text.replace(/((?:gift|voucher|claim|redeem|access|security)\s*(?:card\s*)?(?:code|pin|number)\s*[:#-]?\s*)[^\s<]{4,}/gi, '$1[REDACTED]');
  text = text.replace(/([?&](?:code|pin|token|key|voucher)=)[^&\s]+/gi, '$1[REDACTED]');
  text = text.replace(/\b(?=[A-Z0-9-]{12,}\b)(?=[A-Z0-9-]*[A-Z])(?=[A-Z0-9-]*\d)[A-Z0-9-]{12,}\b/g, '[REDACTED]');
  return text.replace(/\s+/g, ' ').trim().slice(0, 12000);
}
for (const item of $input.all()) {
  const j = item.json || {};
  const messageId = String(j.id || j.messageId || '').trim();
  const sourceFrom = header(item, 'From') || String(j.from || '');
  const sourceSubject = header(item, 'Subject') || String(j.subject || '');
  const redactedBody = redact(j.textPlain || j.text || j.snippet || j.body?.data || '');
  if (!messageId || redactedBody.length < 24) continue;
  if (/mailer-daemon|postmaster|no-?reply.*(delivery|bounce)/i.test(sourceFrom)) continue;
  results.push({ json: {
    ...config,
    messageId,
    threadId: String(j.threadId || ''),
    receivedAt: String(j.internalDate || j.date || new Date().toISOString()),
    sourceFrom,
    sourceSubject,
    redactedBody,
    sourceLink: 'https://mail.google.com/mail/u/0/#all/' + encodeURIComponent(messageId),
  }});
}
return results;

// Build a model-neutral request without placing an API key in the workflow.
const instruction = String.raw`You identify potential consumer value in one redacted email. Return ONLY valid JSON with exactly this schema:
{
  "message_id":"string copied exactly",
  "contains_potential_value":true,
  "value_type":"Gift card|Store credit|Refund|Cashback|Voucher|Rebate|Travel credit|Reward points|Other",
  "merchant_name":"service or merchant name",
  "merchant_domain":"registrable domain only, or empty string",
  "potential_amount":0,
  "currency":"ISO 4217 code or empty string",
  "potential_points":0,
  "expiry_date":"YYYY-MM-DD or null",
  "requires_verification":true,
  "evidence_summary":"short factual explanation without any code, PIN, token, or account number",
  "confidence":0.0,
  "reason":"short explanation"
}
Rules: Return a value only when the message indicates money, credit, points, or a redeemable benefit that may belong to the recipient. Never copy or infer gift-card codes, PINs, URLs with redemption tokens, bank numbers, account numbers, or personal secrets. Potential value is not confirmed value. Never invent an amount, currency, expiry date, or merchant domain.`;
return $input.all().map(item => {
  const j = item.json || {};
  return { json: { ...j, aiRequestBody: { model: j.aiModel, temperature: 0, response_format: { type: 'json_object' }, messages: [{ role: 'user', content: instruction + '\n\nMessage ID: ' + j.messageId + '\nFrom: ' + j.sourceFrom + '\nSubject: ' + j.sourceSubject + '\nReceived: ' + j.receivedAt + '\n\nRedacted email body:\n' + j.redactedBody }] } } };
});

// Restore source context after HTTP Request through the unique Gmail Message ID.
const responses = $input.all();
let sources = [];
try { sources = $('Build Value AI Request').all(); } catch (error) {}
const allowedTypes = new Set(['Gift card', 'Store credit', 'Refund', 'Cashback', 'Voucher', 'Rebate', 'Travel credit', 'Reward points', 'Other']);
const results = [];
function cleanDomain(value) { return String(value || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].replace(/[^a-z0-9.-]/g, ''); }
for (const response of responses) {
  let extraction = {};
  let parseError = '';
  try {
    const raw = response.json?.choices?.[0]?.message?.content || response.json?.output || response.json;
    extraction = typeof raw === 'string' ? JSON.parse(raw.replace(/^\u0060\u0060\u0060json\s*/i, '').replace(/\u0060\u0060\u0060$/i, '').trim()) : raw;
  } catch (error) { parseError = String(error.message || error); }
  const source = sources.find(item => String(item.json?.messageId || '') === String(extraction?.message_id || ''));
  if (!source) continue;
  const confidence = Number(extraction?.confidence);
  const isValue = extraction?.contains_potential_value === true;
  const valueType = allowedTypes.has(String(extraction?.value_type || '')) ? String(extraction.value_type) : 'Other';
  const merchantName = String(extraction?.merchant_name || '').trim();
  const amount = Number(extraction?.potential_amount);
  const points = Number(extraction?.potential_points);
  const hasAmount = Number.isFinite(amount) && amount > 0;
  const hasPoints = Number.isFinite(points) && points > 0;
  const status = !isValue ? 'Ignored' : (parseError || !merchantName || !Number.isFinite(confidence) || confidence < Number(source.json.minimumConfidence || 0.85) ? 'Needs review' : 'Potential');
  const safeSubjectKey = String(source.json.threadId || source.json.messageId || '');
  results.push({ json: {
    ...source.json,
    valueKey: safeSubjectKey + '::' + valueType.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
    containsPotentialValue: isValue,
    valueType,
    merchantName,
    merchantDomain: cleanDomain(extraction?.merchant_domain),
    potentialAmount: hasAmount ? amount : '',
    currency: String(extraction?.currency || '').trim().toUpperCase().replace(/[^A-Z]/g, '').slice(0, 3),
    potentialPoints: hasPoints ? points : '',
    expiryDate: String(extraction?.expiry_date || '').trim() === 'null' ? '' : String(extraction?.expiry_date || '').trim(),
    requiresVerification: extraction?.requires_verification !== false,
    evidenceSummary: String(extraction?.evidence_summary || '').replace(/(?:code|pin|token)\s*[:#-]?\s*[^\s]+/gi, '[REDACTED]').trim(),
    confidence: Number.isFinite(confidence) ? confidence : 0,
    status,
    reviewReason: String(extraction?.reason || parseError || '').trim(),
  }});
}
return results;

// Keep verified, redeemed, ignored, and human-selected actions when fresh evidence arrives.
let proposed = [];
try { proposed = $('Prepare Value Register Row').all(); } catch (error) {}
const existingByKey = new Map($input.all().map(item => [String(item.json?.['Value Key'] || ''), item.json || {}]));
const finalStatuses = new Set(['Verified', 'Redeemed', 'Expired', 'Ignored']);
const results = [];
for (const item of proposed) {
  const row = item.json || {};
  const existing = existingByKey.get(String(row['Value Key'] || '')) || {};
  const existingStatus = String(existing.Status || '').trim();
  results.push({ json: {
    ...row,
    'Status': finalStatuses.has(existingStatus) ? existingStatus : (row.Status || existingStatus || 'Needs review'),
    'First Observed At': existing['First Observed At'] || row['First Observed At'],
    'Desired Action': existing['Desired Action'] || row['Desired Action'] || 'Verify',
    'Redeemed Amount': existing['Redeemed Amount'] || row['Redeemed Amount'] || '',
    'Redeemed At': existing['Redeemed At'] || row['Redeemed At'] || '',
  }});
}
return results;

// Restore the source-backed row after Google Sheets replaces the input.
let rows = [];
try { rows = $('Preserve Human Value Decisions').all(); } catch (error) {}
const results = [];
for (const item of $input.all()) {
  const key = String(item.json?.['Value Key'] || '');
  const source = rows.find(entry => String(entry.json?.['Value Key'] || '') === key);
  if (source) results.push({ json: { ...source.json } });
}
return results;

