// Send only records that still need a human decision; redeemed value is reported separately.
const rows = $input.all().map(item => item.json || {});
let config = {};
try { config = $('Set Template Fields').first().json || {}; } catch (error) {}
const now = new Date();
const urgentMs = Number(config.urgentExpiryDays || 21) * 24 * 60 * 60 * 1000;
let redeemedTotal = 0;
const actionRows = [];
for (const row of rows) {
  const status = String(row.Status || '').trim();
  const redeemed = Number(row['Redeemed Amount']);
  if (Number.isFinite(redeemed) && redeemed > 0) redeemedTotal += redeemed;
  if (['Redeemed', 'Expired', 'Ignored'].includes(status)) continue;
  const expiryText = String(row['Expiry Date'] || '').trim();
  const expiry = expiryText ? new Date(expiryText + 'T23:59:59') : null;
  const expiresSoon = expiry && !Number.isNaN(expiry.getTime()) && expiry.getTime() >= now.getTime() && expiry.getTime() - now.getTime() <= urgentMs;
  const action = String(row['Desired Action'] || 'Verify').trim();
  if (!expiresSoon && action === 'Ignore') continue;
  actionRows.push({ row, expiresSoon, action, expiry });
}
actionRows.sort((a, b) => Number(b.expiresSoon) - Number(a.expiresSoon) || Number(b.row['Potential Amount'] || 0) - Number(a.row['Potential Amount'] || 0));
if (!actionRows.length) return [];
const lines = actionRows.slice(0, 15).map((entry, index) => {
  const r = entry.row;
  const urgency = entry.expiresSoon ? 'EXPIRING SOON' : 'VERIFY';
  const value = r['Potential Amount'] ? r['Potential Amount'] + ' ' + (r.Currency || '') : (r['Potential Points'] ? r['Potential Points'] + ' points' : 'Amount not stated');
  return (index + 1) + '. ' + urgency + ' | ' + (r['Merchant Name'] || 'Unknown merchant') + ' | ' + (r['Value Type'] || 'Other') + ' | ' + value + (r['Expiry Date'] ? ' | Expires ' + r['Expiry Date'] : '') + '\nEvidence: ' + (r['Evidence Summary'] || r['Source Subject'] || '') + '\nSource: ' + (r['Source Link'] || '');
}).join('\n\n');
return [{ json: { ...config, actionCount: actionRows.length, digestBody: 'Inbox Bounty Hunter has ' + actionRows.length + ' potential value record(s) to review.\n\n' + lines + '\n\nValue marked redeemed in this register: ' + redeemedTotal.toFixed(2) + '. Potential value is not confirmed value. Verify each source before acting.' } }];
